def experiment(inputs):
    # Simulate problem candidate evaluation via graph divergence
    candidates = inputs.get('candidates', []) # List of problem structures
    scores = []
    for c in candidates:
        divergence = c.get('divergence', 0)
        cost = c.get('exploration_cost', 1)
        # Prioritize high divergence / low cost ratio
        scores.append(divergence / cost)
    return {'ranked_candidates': scores}

